TS (SELECT 1 FROM quarantined q WHERE q.info_hash=tc.info_hash)\n AND NOT EXISTS (SELECT 1 FROM torrent_contents serving_tc LEFT JOIN content c\n ON (c.type,c.source,c.id)=(serving_tc.content_type,serving_tc.content_source,serving_tc.content_id)\n WHERE serving_tc.info_hash=tc.info_hash AND (serving_tc.content_type='xxx' OR c.adult IS TRUE)) ORDER BY published_at DESC, info_hash DESC, id DESC LIMIT 100"}
