{"at": 1792864678.5943713, "case": "identity_rare", "kind": "prepared_query", "params": ["movie", "synthetic", "123456"], "plan_mode": "auto", "sql": "SELECT tc.id,tc.info_hash FROM torrent_contents tc WHERE tc.content_type=$1 AND tc.content_source=$2 AND tc.content_id=$3 AND EXISTS (SELECT 1 FROM torrents t WHERE t.info_hash=tc.info_hash AND NOT t.private)\n AND NOT EXISTS (SELECT 1 FROM quarantined q WHERE q.info_hash=tc.info_hash)\n AND NOT EXISTS (SELECT 1 FROM torrent_contents serving_tc LEFT JOIN content c\n ON (c.type,c.source,c.id)=(serving_tc.content_type,serving_tc.content_source,serving_tc.content_id)\n WHERE serving_tc.info_hash=tc.info_hash AND (serving_tc.content_type='xxx' OR c.adult IS TRUE)) ORDER BY published_at DESC, info_hash DESC, id DESC LIMIT 100"}
