{"at": 1792864679.1831195, "case": "external_keyset", "kind": "prepared_query", "params": ["movie", "imdb", "tt123456"], "plan_mode": "auto", "sql": "SELECT tc.id,tc.info_hash FROM torrent_contents tc WHERE (tc.content_type,tc.content_source,tc.content_id) IN (VALUES ($1,$2,$3) UNION ALL SELECT content_type,content_source,content_id FROM content_attributes WHERE content_type=$1 AND source=$2 AND value=$3 AND key='id') AND EXISTS (SELECT 1 FROM torrents t WHERE t.info_hash=tc.info_hash AND NOT t.private)\n AND NOT EXISTS (SELECT 1 FROM quarantined q WHERE q.info_hash=tc.info_hash)\n AND NOT EXISTS (SELECT 1 FROM torrent_contents serving_tc LEFT JOIN content c\n ON (c.type,c.source,c.id)=(serving_tc.content_type,serving_tc.content_source,serving_tc.content_id)\n WHERE serving_tc.info_hash=tc.info_hash AND (serving_tc.content_type='xxx' OR c.adult IS TRUE)) ORDER BY published_at DESC, info_hash DESC, id DESC LIMIT 100"}
